{!REQUIRESCRIPT("/soap/ajax/53.0/connection.js")} // Make sure to use the correct API version

function setReviewedByField() {
    var userId = "{!$User.Id}"; // Get the current user's ID

    // Get the record ID from the page
    var recordId = "{!copado__Deployment_Task__c.Id}"; // Replace with your object API name and record ID placeholder

    // Update the reviewed_by__c field
    var fieldsToUpdate = {
        "Id": recordId,
        "reviewed_by__c": userId
    };

    // Create an instance of the Salesforce AJAX toolkit
    var updateRecord = new sforce.SObject("copado__Deployment_Task__c"); // Replace with your object API name
    updateRecord.Id = recordId;
    updateRecord.reviewed_by__c = userId;

    // Update the record in Salesforce
    sforce.connection.update([updateRecord], {
        onSuccess: function(result) {
            alert("Field updated successfully!");
            location.reload(); // Reload the page to reflect the changes
        },
        onFailure: function(error) {
            alert("Error: " + error);
        }
    });
}

// Call the function to set the field value
setReviewedByField();
